pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: deposit amount and caller address (the fuzzer will supply them)
    function testFuzz_property(uint256 depositAmount, address attacker) public {
        // keep domain reasonable: non-zero deposit and a non-zero address
        depositAmount = bound(depositAmount, 1, 1 ether);
        vm.assume(attacker != address(0));

        // deploy an adversarial recipient whose fallback uses lots of gas (to break transfer's 2300 stipend)
        GreedyFallback greedy = new GreedyFallback();

        // fund the adversarial recipient so it can be the msg.sender for deposit
        vm.deal(address(greedy), 0);
        vm.deal(address(this), depositAmount);

        // have the adversarial recipient deposit into c
        vm.prank(address(greedy));
        // call deposit with value; since greedy is a contract, we need to make the call from that contract
        // Use address(greedy).call to invoke c.deposit with value while msg.sender is greedy
        (bool okDeposit, ) = address(greedy).call{value: depositAmount}(abi.encodeWithSelector(greedy.doDeposit.selector, address(c)));
        require(okDeposit);

        // Now invoke withdrawAll from the adversarial recipient and capture whether it reverts/succeeds
        bool refSucceeds;
        vm.prank(address(greedy));
        try c.withdrawAll() {
            refSucceeds = true;
        } catch {
            refSucceeds = false;
        }

        // The single universal assertion: the reference contract (this binary c) must always either succeed
        // or revert consistently with low-level call semantics; specifically here we assert that the reference
        // does NOT revert when paying out to a recipient whose fallback consumes gas (because reference uses
        // low-level call and forwards all gas), i.e. refSucceeds == true for this adversary and any positive deposit.
        // The mutant using transfer would fail (revert) when the recipient consumes >2300 gas; thus this assertion
        // holds for the reference for all inputs and is violated by the mutant for some inputs.
        assertTrue(refSucceeds);
    }
}

// Adversarial helper: will call C.deposit on behalf of itself and has a fallback that consumes substantial gas
contract GreedyFallback {
    // allow external trigger to deposit into C while keeping msg.sender == this contract
    function doDeposit(address cAddr) external payable {
        C(cAddr).deposit{value: msg.value}();
    }

    // fallback that consumes more than 2300 gas to break transfer
    fallback() external payable {
        // burn gas with a loop
        for (uint256 i = 0; i < 1000; i++) {
            // some no-op to consume gas
            uint256 x = i * i;
            x;
        }
    }
}

