pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz: amount to deposit and a boolean whether the recipient will revert.
    // We model the recipient as either a normal EOA-like receiver (an attacker contract with payable receive that accepts)
    // or a Reverter that always reverts on receive. We deploy both and pass their addresses by using vm.prank.
    function testFuzz_property(uint128 depositAmount, bool willRevert) public {
        vm.assume(depositAmount > 0); // keep wide but non-zero to exercise withdraw

        // choose recipient based on willRevert
        address recipient = willRevert ? address(new Reverter()) : address(new Acceptor());

        // fund the depositor (actor) and perform deposit
        address depositor = address(0xABCD);
        vm.deal(depositor, uint256(depositAmount));
        vm.prank(depositor);
        c.deposit{value: uint256(depositAmount)}();

        // sanity: contract should hold the deposited funds
        // now attempt withdrawAll as depositor, sending to the recipient by using a proxy that forwards to recipient
        // we need the low-level call to go to depositor (msg.sender) so we make the depositor be the recipient by having the depositor be a contract
        // Instead, we simulate that depositor is the caller and the low-level call will go to depositor (EOA). To force an external call that can revert,
        // we make the depositor be a small contract that in its fallback forwards to chosen recipient. Deploy a CallerProxy that will call withdrawAll

        CallerProxy proxy = new CallerProxy(c, recipient);
        // fund proxy with zero; the contract will send funds to proxy address (which will forward to recipient)
        // but withdrawAll sends to msg.sender, so we must make proxy be the msg.sender when calling withdrawAll

        // ensure proxy has no initial balance
        vm.deal(address(proxy), 0);

        // Make proxy call withdrawAll as msg.sender
        // First, transfer custody of the deposit: we need the credit to be recorded for proxy, so deposit must have been from proxy.
        // So redo: deposit from proxy instead of depositor.
        // Reset state: create a fresh contract and deposit from proxy
        c = new C();
        vm.deal(address(proxy), uint256(depositAmount));
        vm.prank(address(proxy));
        c.deposit{value: uint256(depositAmount)}();

        // Capture contract balance before withdraw
        uint256 beforeBal = address(c).balance;

        // Execute withdrawAll from proxy which will cause c to call proxy (msg.sender) and proxy will forward to recipient.
        // The proxy's fallback will forward the funds to recipient, which may revert.
        bool ok;
        try proxy.doWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General property to assert: In the correct contract, after withdrawAll completes (either success or handled revert),
        // the stored credit for the proxy is zero iff the contract's balance decreased by the withdrawn amount (i.e., if the external send succeeded,
        // the contract balance is beforeBal - depositAmount and credit is 0; if the external send reverted, the reference contract will not have zeroed credit
        // (or will have consistent accounting), but the mutant can break this relation.
        // We read the public getter for credit via a helper view function: C has no public credit getter, so we rely on observable address(c).balance
        // and the success boolean of the withdraw call. The allowed assert must read c's public surface; we use address(c).balance and ok.

        // For the reference contract, successful withdraw (ok==true) implies address(c).balance == beforeBal - depositAmount.
        // Conversely, if ok==false (external revert), reference contract should not have lost the funds, so address(c).balance == beforeBal.
        // Thus assert that (ok && address(c).balance == beforeBal - uint256(depositAmount)) || (!ok && address(c).balance == beforeBal)

        bool property = (ok && address(c).balance == beforeBal - uint256(depositAmount)) || (!ok && address(c).balance == beforeBal);
        assertTrue(property);
    }
}

// Proxy that calls withdrawAll on C and forwards any received ETH to a chosen recipient (which may revert).
contract CallerProxy {
    C immutable c;
    address immutable recipient;
    constructor(C _c, address _recipient) {
        c = _c;
        recipient = _recipient;
    }
    function doWithdrawAll() external {
        c.withdrawAll();
    }
    receive() external payable {
        // forward to recipient; this may revert if recipient reverts
        (bool s, ) = recipient.call{value: msg.value}("");
        require(s);
    }
}

contract Reverter {
    receive() external payable {
        revert("boom");
    }
}

contract Acceptor {
    receive() external payable {}
}

