pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: amount to deposit and a boolean deciding whether recipient will revert
    function testFuzz_property(uint128 depositAmount, bool recipientReverts) public {
        // keep amount within reasonable bounds and non-zero to be meaningful
        uint256 amount = bound(uint256(depositAmount), 1, 1 ether);

        // deploy adversarial recipient that optionally reverts in receive()
        RevertingOrNot r = new RevertingOrNot(recipientReverts);

        // fund the depositor (use the helper contract as the depositor to make the subsequent low-level send go to it)
        address depositor = address(r); // use helper as both depositor and recipient target
        vm.deal(depositor, amount);

        // make a deposit from depositor into c
        vm.prank(depositor);
        c.deposit{value: amount}();

        // record pre-withdraw state
        uint256 preContractBalance = address(c).balance;
        // call withdrawAll which will attempt to send to depositor (the helper)
        bool ok;
        vm.prank(depositor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After withdrawAll, the reference implementation guarantees that if the external send reverted (ok==false),
        // the contract's balance remains equal to the stored aggregated credits (i.e., it did not lose funds nor zero out credit incorrectly).
        // We observe this by checking that if the external send reverted, then address(c).balance == preContractBalance
        // (reference keeps balance unchanged on revert), whereas the mutant that zeroes credit before decrement may have cleared credit while leaving balance unchanged,
        // producing a mismatch between stored credits and balance; checking balance equality to preContractBalance distinguishes them.

        if (!ok) {
            // when recipient reverted, reference preserves funds: contract balance unchanged
            assertTrue(address(c).balance == preContractBalance);
        } else {
            // when send succeeded, contract balance should have decreased by amount
            assertTrue(address(c).balance == preContractBalance - amount);
        }
    }
}

// helper that acts as depositor and optionally reverts when receiving funds
contract RevertingOrNot {
    bool public doRevert;
    constructor(bool _doRevert) payable {
        doRevert = _doRevert;
    }
    receive() external payable {
        if (doRevert) revert("revert on receive");
    }
}

