import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReceiveReverter reverter;

    function setUp() public { c = new C(); reverter = new ReceiveReverter(); }

    // fuzzed params: amount to deposit and a boolean choose whether recipient will revert
    function testFuzz_property(uint128 amount, bool willRevert) public {
        // keep amount in reasonable bounds but wide
        uint256 amt = bound(uint256(amount), 1, 1 ether);

        // actor who deposits and later calls withdrawAll
        address depositor = address(0xABCD);
        vm.deal(depositor, amt);

        // deposit
        vm.prank(depositor);
        c.deposit{value: amt}();

        // pick recipient: either a normal EOA (address with no code) or a reverter contract
        address recipient = willRevert ? address(reverter) : address(0xBEEF);

        // make msg.sender be depositor and call withdrawAll, but route the low-level call target
        // To force c to send to depositor we need depositor to be the callee; instead we simulate by making depositor be the recipient
        // For the failing case we want the external send to depositor to fail; EOAs never fail, so we use the reverter deployed above
        // Use vm.prank with the depositor to call withdrawAll; when willRevert is true, we instead make depositor equal reverter so the low-level call targets a contract that reverts

        if (willRevert) {
            // make the depositor be the reverter contract: we cannot change msg.sender to a contract, but we can have the depositor address be the one that previously deposited by using an intermediate: deposit used depositor EOA, but withdrawAll's msg.sender determines which credit is used. To make the low-level external send target a reverting contract, we simulate by having the depositor address be the reverter contract address when calling withdrawAll.
            // First, credit the reverter contract's entry so it has credit to withdraw
            // To do this, have the reverter contract deposit directly
            vm.deal(address(reverter), amt);
            vm.prank(address(reverter));
            c.deposit{value: amt}();

            // record balance before
            uint256 beforeBal = address(c).balance;

            // call withdrawAll from the reverter (the recipient will revert on receiving funds)
            bool ok;
            vm.prank(address(reverter));
            try c.withdrawAll() {
                ok = true;
            } catch {
                ok = false;
            }

            // After call (either returned or reverted), check the invariant: if stored credit for reverter is zero then contract balance must have decreased by amt
            // Access credit via auto getter: credit is private in original; but specification allowed only public getters — since credit in C is not public, we cannot read it. Instead we observe the universal property via address(c).balance change in relation to whether withdraw succeeded.
            // For the reference contract, when the external send reverts, the call to withdrawAll will revert and the state will be unchanged (balance unchanged). For mutant, since it zeroes credit before external call, the call will revert but stored credit became 0 while balance unchanged. We detect this by checking whether the call reverted (ok==false) implies address(c).balance == beforeBal (reference) and mutant may violate; thus we assert that when ok==false then balance == beforeBal.

            assertTrue(!(ok == false) || address(c).balance == beforeBal);

        } else {
            // Non-reverting recipient: use EOA depositor
            // We already deposited from depositor earlier. Record before balance
            uint256 beforeBal = address(c).balance;

            // withdrawAll should succeed
            vm.prank(depositor);
            bool ok;
            try c.withdrawAll() {
                ok = true;
            } catch {
                ok = false;
            }

            // If call succeeded, contract balance must have decreased by amt
            assertTrue(!(ok == true) || address(c).balance == beforeBal - amt);
        }
    }
}

